//! FX library — Rust side of the shared effects manifest
//! (`shared/fx/manifest.json`, generated by `shared/fx/build.ts`).
//!
//! Responsibilities:
//!  - parse the embedded manifest and look entries up by id;
//!  - validate/clamp parameters exactly like `src/lib/fx/manifest.ts`;
//!  - expand recipe templates byte-for-byte like the TS side
//!    (`shared/fx/golden.json` pins both);
//!  - build the NATIVE ffmpeg graph for library transitions.
//!
//! Why native graphs: evaluating a recipe per pixel inside ffmpeg
//! (`xfade=custom`) measured ~0.5 s/frame at 1080p for a 6-tap blur, and
//! `st/ld` slots race across xfade's slice threads. The graphs below are
//! O(1) per pixel — a 1 s Velocity Swipe at 1080p adds well under a second
//! of render time. The recipe `expr` remains the *specification*: the
//! preview transpiles it to GLSL and tests bound the native output against it.

use crate::project::document::Transition;
use serde::Deserialize;
use std::collections::BTreeMap;
use std::sync::OnceLock;

const MANIFEST_JSON: &str = include_str!("../../../shared/fx/manifest.json");

#[derive(Debug, Clone, Deserialize)]
pub struct FxParam {
    pub key: String,
    #[serde(rename = "type")]
    pub ty: String,
    pub def: f64,
    #[serde(default)]
    pub min: Option<f64>,
    #[serde(default)]
    pub max: Option<f64>,
    #[serde(default)]
    pub options: Option<Vec<String>>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Derive {
    pub from: String,
    pub values: Vec<f64>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "kind", rename_all = "lowercase")]
pub enum FxRender {
    Strip,
    Fields {
        div: u32,
        fields: BTreeMap<String, String>,
    },
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FxEntry {
    pub id: String,
    pub kind: String,
    #[serde(default)]
    pub category: String,
    pub params: Vec<FxParam>,
    #[serde(default)]
    pub derive: BTreeMap<String, Derive>,
    #[serde(default)]
    pub expr: Option<String>,
    #[serde(default)]
    pub render: Option<FxRender>,
    #[serde(default)]
    pub default_ease: Option<String>,
    #[serde(default)]
    pub requires: Vec<String>,
    /// kind:"filter" — color ops baked into the 33³ .cube (fxlut.rs).
    #[serde(default)]
    pub lut: Option<Vec<crate::render::fxlut::LutOp>>,
}

#[derive(Debug, Deserialize)]
pub struct FxManifest {
    pub eases: BTreeMap<String, String>,
    pub capabilities: BTreeMap<String, bool>,
    pub entries: Vec<FxEntry>,
}

pub fn manifest() -> &'static FxManifest {
    static M: OnceLock<FxManifest> = OnceLock::new();
    M.get_or_init(|| {
        serde_json::from_str(MANIFEST_JSON).expect("shared/fx/manifest.json is invalid")
    })
}

pub fn entry(id: &str) -> Option<&'static FxEntry> {
    manifest().entries.iter().find(|e| e.id == id)
}

// ── parameters ────────────────────────────────────────────────────────

/// Clamp one value into its spec — mirrors manifest.ts::sanitizeParam.
fn sanitize(spec: &FxParam, v: Option<f64>) -> f64 {
    let Some(v) = v.filter(|v| v.is_finite()) else {
        return spec.def;
    };
    match spec.ty.as_str() {
        "enum" => v
            .round()
            .clamp(0.0, (spec.options.as_ref().map_or(1, |o| o.len()) - 1) as f64),
        "bool" => (v >= 0.5) as u8 as f64,
        "color" => v.round().clamp(0.0, 16_777_215.0),
        _ => v.clamp(spec.min.unwrap_or(f64::MIN), spec.max.unwrap_or(f64::MAX)),
    }
}

/// Validated params (unknown keys dropped, bad values clamped) plus the
/// constants derived from enums. Never fails: bad data degrades.
pub fn resolve_constants(e: &FxEntry, params: &BTreeMap<String, f64>) -> BTreeMap<String, f64> {
    let mut out: BTreeMap<String, f64> = e
        .params
        .iter()
        .map(|s| (s.key.clone(), sanitize(s, params.get(&s.key).copied())))
        .collect();
    for (name, d) in &e.derive {
        let idx = (out.get(&d.from).copied().unwrap_or(0.0).round() as i64)
            .clamp(0, d.values.len() as i64 - 1) as usize;
        out.insert(name.clone(), d.values[idx]);
    }
    out
}

/// Names of capabilities an entry needs that this build lacks.
pub fn missing_capabilities(e: &FxEntry) -> Vec<String> {
    e.requires
        .iter()
        .filter(|c| !manifest().capabilities.get(*c).copied().unwrap_or(false))
        .cloned()
        .collect()
}

// ── template expansion (byte-identical with manifest.ts) ──────────────

/// Deterministic number text: integers verbatim, else 6 decimals trimmed;
/// negatives parenthesised so `a-{x}` stays valid.
pub fn fmt_num(v: f64) -> String {
    let mut s = if v == v.trunc() && v.abs() < 1e15 {
        format!("{}", v as i64)
    } else {
        let t = format!("{v:.6}");
        t.trim_end_matches('0').trim_end_matches('.').to_string()
    };
    if s == "-0" {
        s = "0".into();
    }
    if v < 0.0 {
        format!("({s})")
    } else {
        s
    }
}

/// Expand `{T}`, `{u}` (→ `(u_expr)`) and `{name}` in recipe text.
/// Unknown names are an error — a manifest typo must never render garbage.
pub fn expand_text(
    e: &FxEntry,
    text: &str,
    params: &BTreeMap<String, f64>,
    ease: Option<&str>,
    u_expr: &str,
) -> Result<String, String> {
    let m = manifest();
    let ease_name = ease
        .filter(|n| m.eases.contains_key(*n))
        .or(e.default_ease.as_deref())
        .unwrap_or("linear");
    let consts = resolve_constants(e, params);
    let with_t = text.replace("{T}", &m.eases[ease_name]);
    let mut out = String::with_capacity(with_t.len());
    let mut rest = with_t.as_str();
    while let Some(i) = rest.find('{') {
        out.push_str(&rest[..i]);
        let tail = &rest[i + 1..];
        let j = tail.find('}').ok_or_else(|| format!("{}: unclosed '{{'", e.id))?;
        let name = &tail[..j];
        if name == "u" {
            out.push('(');
            out.push_str(u_expr);
            out.push(')');
        } else if let Some(v) = consts.get(name) {
            out.push_str(&fmt_num(*v));
        } else {
            return Err(format!("{}: unknown placeholder {{{name}}}", e.id));
        }
        rest = &tail[j + 1..];
    }
    out.push_str(rest);
    Ok(out)
}

// ── native transition graphs ──────────────────────────────────────────

/// Geometry/timing of one library transition inside a group chain.
pub struct GraphCtx {
    pub w: u32,
    pub h: u32,
    pub fps_num: u32,
    pub fps_den: u32,
    /// Frames in the outgoing stream (everything accumulated so far).
    pub a_frames: u32,
    /// Frames in the incoming clip.
    pub b_frames: u32,
    /// Frames the transition overlaps.
    pub n_t: u32,
}

pub fn ms_to_frames(ms: i64, fps_num: u32, fps_den: u32) -> u32 {
    ((ms as f64 * fps_num as f64) / (fps_den as f64 * 1000.0)).round().max(0.0) as u32
}

/// Is this transition kind a library transition with a native graph?
pub fn library_transition(kind: &str) -> Option<&'static FxEntry> {
    entry(kind).filter(|e| e.kind == "transition" && e.render.is_some())
}

pub fn ident_replace(s: &str, ident: &str, with: &str) -> String {
    let b = s.as_bytes();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if s[i..].starts_with(ident)
            && (i == 0 || !(b[i - 1].is_ascii_alphanumeric() || b[i - 1] == b'_'))
            && s[i + ident.len()..]
                .bytes()
                .next()
                .map_or(true, |c| !(c.is_ascii_alphanumeric() || c == b'_'))
        {
            out.push_str(with);
            i += ident.len();
        } else {
            let ch = s[i..].chars().next().unwrap();
            out.push(ch);
            i += ch.len_utf8();
        }
    }
    out
}

/// Build the filters of one library transition. `a`/`b` are the stream
/// labels (with brackets); the result ends in `out`. `uid` keeps internal
/// labels unique across transitions. Returns None for non-library kinds.
pub fn transition_graph(
    tr: &Transition,
    ctx: &GraphCtx,
    a: &str,
    b: &str,
    out: &str,
    uid: &str,
) -> Option<Vec<String>> {
    let e = library_transition(&tr.kind)?;
    let n_t = ctx.n_t.min(ctx.a_frames).min(ctx.b_frames).max(1);
    let n_head = ctx.a_frames - n_t;
    let b_rest = ctx.b_frames - n_t;
    let ease = tr.ease.as_deref();
    let l = |s: &str| format!("[{uid}{s}]");
    let mut f: Vec<String> = Vec::new();

    // Split the outgoing stream into head (untouched) and tail (overlap);
    // the incoming clip into head (overlap) and rest.
    let a_tail = l("at");
    if n_head > 0 {
        f.push(format!("{a}split=2{}{}", l("ah0"), l("at0")));
        f.push(format!(
            "{}trim=end_frame={n_head},setpts=PTS-STARTPTS,format=rgba,setsar=1{}",
            l("ah0"),
            l("ah")
        ));
        f.push(format!(
            "{}trim=start_frame={n_head}:end_frame={},setpts=PTS-STARTPTS,format=gbrap{a_tail}",
            l("at0"),
            n_head + n_t
        ));
    } else {
        f.push(format!(
            "{a}trim=end_frame={n_t},setpts=PTS-STARTPTS,format=gbrap{a_tail}"
        ));
    }
    let b_head = l("bt");
    if b_rest > 0 {
        f.push(format!("{b}split=2{}{}", l("bh0"), l("br0")));
        f.push(format!(
            "{}trim=end_frame={n_t},setpts=PTS-STARTPTS,format=gbrap{b_head}",
            l("bh0")
        ));
        f.push(format!(
            "{}trim=start_frame={n_t},setpts=PTS-STARTPTS,format=rgba,setsar=1{}",
            l("br0"),
            l("br")
        ));
    } else {
        f.push(format!(
            "{b}trim=end_frame={n_t},setpts=PTS-STARTPTS,format=gbrap{b_head}"
        ));
    }

    // The transition itself → [tr] (gbrap, n_t frames).
    let tr_lbl = l("tr");
    let (w, h) = (ctx.w as f64, ctx.h as f64);
    let fps = format!("{}/{}", ctx.fps_num, ctx.fps_den);
    match e.render.as_ref()? {
        FxRender::Strip => {
            let c = resolve_constants(e, &tr.params);
            let (dx, dy) = (c["dx"], c["dy"]);
            let blur = c["blur"];
            let horizontal = dx != 0.0;
            // Progress inside crop's per-frame expression: n = frame index.
            let u = format!("(n+0.5)/{n_t}");
            let t = expand_text(e, "{T}", &tr.params, ease, &u).ok()?;
            // Strip order: forward motion (left/up) = [A|B] from offset 0→1,
            // reverse (right/down) = [B|A] from offset 1→0.
            let reverse = dx > 0.0 || dy > 0.0;
            let (first, second) = if reverse { (&b_head, &a_tail) } else { (&a_tail, &b_head) };
            let stack = if horizontal { "hstack" } else { "vstack" };
            let strip = l("strip");
            f.push(format!("{first}{second}{stack}=inputs=2{strip}"));
            let taps = if blur > 0.0 { 6 } else { 1 };
            let span = if horizontal { w } else { h };
            let mut crops = Vec::new();
            if taps > 1 {
                let mut outs = String::new();
                for k in 0..taps {
                    outs.push_str(&l(&format!("s{k}")));
                }
                f.push(format!("{strip}split={taps}{outs}"));
            }
            for k in 0..taps {
                let s = if taps > 1 { k as f64 / (taps - 1) as f64 - 0.5 } else { 0.0 };
                let m = format!("{blur}*sin(PI*{t})");
                // Window offset in px along the motion axis.
                let off = if reverse {
                    format!("{span}*(1-{t}+({s})*{m})")
                } else {
                    format!("{span}*({t}+({s})*{m})")
                };
                // crop ROUNDS x/y while the spec samples floor(): shift by -0.5.
                let off = format!("({off}-0.5)");
                let (cx, cy) = if horizontal { (off, "0".to_string()) } else { ("0".to_string(), off) };
                let src = if taps > 1 { l(&format!("s{k}")) } else { strip.clone() };
                let dst = l(&format!("c{k}"));
                f.push(format!("{src}crop=w={}:h={}:x='{cx}':y='{cy}'{dst}", ctx.w, ctx.h));
                crops.push(dst);
            }
            if taps > 1 {
                let weights = vec!["1"; taps].join(" ");
                f.push(format!(
                    "{}mix=inputs={taps}:weights='{weights}'{tr_lbl}",
                    crops.join("")
                ));
            } else {
                f.push(format!("{}copy{tr_lbl}", crops[0]));
            }
        }
        FxRender::Fields { div, fields } => {
            // Field resolution: ~135 texels over the height whatever the
            // canvas (keeps the fastest wobble ≥ ~20 texels per period),
            // capped by the manifest's `div`. Small canvases get full-res
            // fields — they are cheap there.
            let div = (h / 135.0).round().clamp(1.0, (*div).max(1) as f64);
            let (lw, lh) = (((w / div).ceil() as u32).max(2), ((h / div).ceil() as u32).max(2));
            let u = format!("(N+0.5)/{n_t}");
            let secs = (n_t as f64 + 1.0) * ctx.fps_den as f64 / ctx.fps_num as f64;
            let field = |name: &str, fmt: &str, wrap: &dyn Fn(&str) -> String| -> Option<String> {
                let text = expand_text(e, fields.get(name)?, &tr.params, ease, &u).ok()?;
                // Field texel (X,Y) represents canvas pixel centre ((X+.5)·div−.5).
                let cx = format!("((X+0.5)*{div}-0.5)");
                let cy = format!("((Y+0.5)*{div}-0.5)");
                let t = ident_replace(&text, "X", "§X");
                let t = ident_replace(&t, "Y", "§Y");
                let t = ident_replace(&t, "W", &fmt_num(w));
                let t = ident_replace(&t, "H", &fmt_num(h));
                let t = t.replace("§X", &cx).replace("§Y", &cy);
                Some(format!(
                    "color=c=black:s={lw}x{lh}:r={fps}:d={secs:.4},format={fmt},geq=lum='{}',trim=end_frame={n_t},scale={}:{}:flags=bilinear",
                    wrap(&t),
                    ctx.w,
                    ctx.h
                ))
            };
            let clamp_x = |t: &str| format!("clip({t},0,{})", ctx.w - 1);
            let clamp_y = |t: &str| format!("clip({t},0,{})", ctx.h - 1);
            let mask = |t: &str| format!("255*clip({t},0,1)");
            let (fax, fay, fm) = (l("fax"), l("fay"), l("fm"));
            f.push(format!("{}{fax}", field("ax", "gray16le", &clamp_x)?));
            f.push(format!("{}{fay}", field("ay", "gray16le", &clamp_y)?));
            f.push(format!("{}{fm}", field("m", "gray", &mask)?));
            let warped = l("warp");
            f.push(format!("{a_tail}{fax}{fay}remap{warped}"));
            let merged = if fields.contains_key("glow") {
                l("mrg")
            } else {
                tr_lbl.clone()
            };
            f.push(format!("{b_head}{warped}{fm}maskedmerge{merged}"));
            // Optional additive light field: luma 0..1 baked at field res,
            // tinted per channel via cr/cg/cb constants, screen-blended
            // over the merged frames (spec: M+(255-M)·G·tint/255).
            if let Some(glow_t) = fields.get("glow") {
                let c = resolve_constants(e, &tr.params);
                let tint = |k: &str| {
                    fmt_num(c.get(k).copied().unwrap_or(255.0).clamp(0.0, 255.0))
                };
                let text = expand_text(e, glow_t, &tr.params, ease, &u).ok()?;
                let cx = format!("((X+0.5)*{div}-0.5)");
                let cy = format!("((Y+0.5)*{div}-0.5)");
                let t = ident_replace(&text, "X", "§X");
                let t = ident_replace(&t, "Y", "§Y");
                let t = ident_replace(&t, "W", &fmt_num(w));
                let t = ident_replace(&t, "H", &fmt_num(h));
                let t = t.replace("§X", &cx).replace("§Y", &cy);
                let fg = l("fg");
                // geq output is uint8 and wraps mod 256 — the glow can
                // exceed 1.0 so clamp each channel like the spec's min().
                f.push(format!(
                    "color=c=black:s={lw}x{lh}:r={fps}:d={secs:.4},format=gbrp,geq=r='min(({t})*{tr_t},255)':g='min(({t})*{tg_t},255)':b='min(({t})*{tb_t},255)',trim=end_frame={n_t},scale={}:{}:flags=bilinear{fg}",
                    ctx.w,
                    ctx.h,
                    t = t,
                    tr_t = tint("cr"),
                    tg_t = tint("cg"),
                    tb_t = tint("cb"),
                ));
                f.push(format!("{merged}{fg}blend=all_mode='screen'{tr_lbl}"));
            }
        }
    }

    // Reassemble: head · transition · rest.
    let tr_rgba = l("trf");
    f.push(format!("{tr_lbl}format=rgba,setsar=1{tr_rgba}"));
    let mut parts: Vec<String> = Vec::new();
    if n_head > 0 {
        parts.push(l("ah"));
    }
    parts.push(tr_rgba);
    if b_rest > 0 {
        parts.push(l("br"));
    }
    if parts.len() == 1 {
        f.push(format!("{}null{out}", parts[0]));
    } else {
        f.push(format!(
            "{}concat=n={}:v=1:a=0{out}",
            parts.join(""),
            parts.len()
        ));
    }
    Some(f)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// shared/fx/golden.json — written by the TS suite, pins both sides.
    fn golden() -> BTreeMap<String, String> {
        serde_json::from_str(include_str!("../../../shared/fx/golden.json")).unwrap()
    }

    #[test]
    fn expansions_match_ts_golden() {
        let g = golden();
        let none = BTreeMap::new();
        let mut checked = 0;
        for e in &manifest().entries {
            if let Some(expr) = &e.expr {
                let got = expand_text(e, expr, &none, None, "u").unwrap();
                assert_eq!(&got, &g[&format!("{}.expr", e.id)], "{}.expr", e.id);
                checked += 1;
            }
            if let Some(FxRender::Fields { fields, .. }) = &e.render {
                for (k, v) in fields {
                    let got = expand_text(e, v, &none, None, "(N+0.5)/NT").unwrap();
                    assert_eq!(&got, &g[&format!("{}.field.{k}", e.id)], "{}.field.{k}", e.id);
                    checked += 1;
                }
            }
        }
        let sw = entry("velocitySwipe").unwrap();
        let p: BTreeMap<String, f64> = [("direction".to_string(), 3.0), ("blur".to_string(), 0.25)].into();
        let got = expand_text(sw, sw.expr.as_ref().unwrap(), &p, Some("easeOut"), "u").unwrap();
        assert_eq!(got, g["velocitySwipe.expr.down"]);
        assert!(checked >= 3);
    }

    #[test]
    fn validation_clamps_and_derives() {
        let sw = entry("velocitySwipe").unwrap();
        let p: BTreeMap<String, f64> = [
            ("blur".to_string(), 9.0),
            ("direction".to_string(), 7.4),
            ("bogus".to_string(), 1.0),
        ]
        .into();
        let c = resolve_constants(sw, &p);
        assert_eq!(c["blur"], 0.4);
        assert_eq!(c["direction"], 3.0);
        assert_eq!((c["dx"], c["dy"]), (0.0, 1.0));
        assert!(!c.contains_key("bogus"));
        let nan: BTreeMap<String, f64> = [("blur".to_string(), f64::NAN)].into();
        assert_eq!(resolve_constants(sw, &nan)["blur"], 0.16);
    }

    #[test]
    fn number_formatting_is_deterministic() {
        assert_eq!(fmt_num(3.0), "3");
        assert_eq!(fmt_num(0.16), "0.16");
        assert_eq!(fmt_num(-1.0), "(-1)");
        assert_eq!(fmt_num(-0.5), "(-0.5)");
        assert_eq!(fmt_num(-0.0), "0");
        assert_eq!(fmt_num(0.1 + 0.2), "0.3");
    }

    #[test]
    fn unknown_placeholder_is_an_error() {
        let sw = entry("velocitySwipe").unwrap();
        assert!(expand_text(sw, "{nope}", &BTreeMap::new(), None, "u").is_err());
    }
}
